package com.mahesh.empleave.leavetype;import com.mahesh.empleave.audit.*;import com.mahesh.empleave.common.dto.*;import com.mahesh.empleave.user.*;import jakarta.validation.constraints.*;import lombok.*;import org.springframework.security.access.prepost.*;import org.springframework.security.core.*;import org.springframework.web.bind.annotation.*;import java.util.*;@RestController @RequestMapping("/api/leave-types") @RequiredArgsConstructor public class LeaveTypeController{private final LeaveTypeRepository repo;private final UserRepository users;private final AuditService audit;record Input(@NotBlank @Size(max=80) String name){}@GetMapping List<ApiDtos.LeaveType> list(){return repo.findAll().stream().map(ApiDtos::leaveType).toList();}@PostMapping @PreAuthorize("hasRole('ADMIN')") ApiDtos.LeaveType add(Authentication a,@RequestBody @jakarta.validation.Valid Input x){var t=repo.save(new LeaveType(x.name()));audit.log(users.findByEmail(a.getName()).orElseThrow(),"LEAVE_TYPE_CREATED","LEAVE_TYPE",t.getId());return ApiDtos.leaveType(t);}@PutMapping("/{id}/active") @PreAuthorize("hasRole('ADMIN')") ApiDtos.LeaveType active(Authentication a,@PathVariable Long id,@RequestParam boolean value){var t=repo.findById(id).orElseThrow();t.setActive(value);t=repo.save(t);audit.log(users.findByEmail(a.getName()).orElseThrow(),"LEAVE_TYPE_UPDATED","LEAVE_TYPE",id);return ApiDtos.leaveType(t);}}
